export function updateEffects(dt,state,callbacks){let {pending,shots,impacts,scene}=state;const {resolveAOE,resolveAttack,applyDamage}=callbacks;for(let i=pending.length-1;i>=0;i--){const p=pending[i];p.remaining-=dt;if(p.remaining<=0){pending.splice(i,1);p.aoe?resolveAOE(p.a,p.b):resolveAttack(p.a,p.b)}}for(let i=shots.length-1;i>=0;i--){const p=shots[i];p.age+=dt;const t=Math.min(1,p.age/p.duration);p.core.position.lerpVectors(p.start,p.end,t);if(p.kind==='spell'){p.core.scale.setScalar(1+Math.sin(t*Math.PI)*.6);p.core.rotation.y+=dt*8}if(p.glow)p.glow.position.copy(p.core.position);if(t>=1){scene.remove(p.core);if(p.glow)scene.remove(p.glow);shots.splice(i,1);if(!p.target.dead)applyDamage(p.attacker,p.target,p.kind==='spell'?'#8bc7ff':'#ffe29b')}}for(let i=impacts.length-1;i>=0;i--){const p=impacts[i];p.age+=dt;const t=Math.min(1,p.age/p.duration);if(p.velocity)p.mesh.position.addScaledVector(p.velocity,dt);else p.mesh.scale.setScalar(1+t*6);p.mesh.material.opacity=1-t;if(t>=1){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();impacts.splice(i,1)}}state.shake=Math.max(0,state.shake-dt*.65);state.flash=Math.max(0,state.flash-dt)}
